WITH employees_by_department AS (SELECT dept_id, ROUND(AVG(salary), 2) AS avg_salary, SUM(CASE WHEN job_title = 'Director' THEN salary ELSE 0 END) AS director_salary FROM employees WHERE job_title IN ('Manager', 'Designer', 'Engineer') GROUP BY dept_id) SELECT d.location, ebd.avg_salary, ebd.director_salary FROM departments d LEFT JOIN employees_by_department ebd ON d.id = ebd.dept_id WHERE ebd.director_salary >= 23;
